package ru.bububu.radio.core;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.*;
public final class NoteDraftStoreTest {
    @Rule public TemporaryFolder tmp=new TemporaryFolder();
    @Test public void unicodeDraftSurvivesNewOwnerAndExplicitDiscardClearsOnlyDraft()throws Exception{File directory=tmp.newFolder();NoteDraftStore store=new NoteDraftStore(directory,n->assertTrue(n>0));NoteDraftStore.Draft d=new NoteDraftStore.Draft("note",7,"Название","Ручной текст 😀");store.save(Arrays.asList(d));NoteDraftStore.Draft restored=new NoteDraftStore(directory,n->{}).load().get("note");assertEquals(7,restored.revision);assertEquals(d.text,restored.text);store.save(Collections.emptyList());assertTrue(store.load().isEmpty());}
    @Test public void quotaFailurePreservesCommittedDraftAndCorruptOrSymlinkIsNotApplied()throws Exception{File directory=tmp.newFolder();NoteDraftStore initial=new NoteDraftStore(directory,n->{});initial.save(Arrays.asList(new NoteDraftStore.Draft("n",1,"t","old")));try{new NoteDraftStore(directory,n->{throw new IllegalStateException("full");}).save(Arrays.asList(new NoteDraftStore.Draft("n",1,"t","new")));fail();}catch(IllegalStateException expected){}assertEquals("old",initial.load().get("n").text);Files.write(new File(directory,"editing-drafts.bin").toPath(),new byte[]{1,2});try{initial.load();fail();}catch(IOException expected){} }
    private void denied(File part,File original,Object key,boolean stopped,boolean certain)throws Exception{try{PendingTake.discard(part,original,key,stopped,certain);fail();}catch(IOException expected){assertTrue(part.exists());}}
    @Test public void pendingTakeDiscardRequiresSameUnpublishedFileAndConfirmedStop()throws Exception{File directory=tmp.newFolder();File part=new File(directory,"123e4567-e89b-12d3-a456-426614174000.wav.part"),original=new File(directory,"123e4567-e89b-12d3-a456-426614174000.wav");Files.write(part.toPath(),new byte[]{1});Object key=PendingTake.identity(part);denied(part,original,key,false,true);denied(part,original,key,true,false);denied(part,original,new Object(),true,true);Files.write(original.toPath(),new byte[]{2});denied(part,original,key,true,true);assertTrue(part.exists());Files.delete(original.toPath());PendingTake.discard(part,original,key,true,true);assertFalse(part.exists());}
}
